function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof AZLAN_INFO&&(e.innerHTML=AZLAN_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderGoldCampaigns(){const e=document.getElementById("gold-grid");e&&"undefined"!=typeof INDIA_GOLD_CAMPAIGNS&&(e.innerHTML=INDIA_GOLD_CAMPAIGNS.map(e=>`\n        <div class="gold-card">\n            <div class="card-header">\n                <h3>🥇 ${e.year} (${e.edition})</h3>\n                <span class="score-badge">${e.finalScore}</span>\n            </div>\n            <p>${e.highlight}</p>\n        </div>\n    `).join(""))}function renderMedals(){const e=document.getElementById("medals-grid");e&&"undefined"!=typeof MEDAL_RECORD&&(e.innerHTML=MEDAL_RECORD.map(e=>`\n        <div class="medal-card">\n            <h3>🏅 ${e.type}</h3>\n            <p><strong>Editions Won:</strong> ${e.years}</p>\n        </div>\n    `).join(""))}function renderLegends(){const e=document.getElementById("legends-grid");e&&"undefined"!=typeof NOTABLE_LEGENDS&&(e.innerHTML=NOTABLE_LEGENDS.map(e=>`\n        <div class="legend-card">\n            <span class="role-tag">${e.role}</span>\n            <h3>${e.icon} ${e.name}</h3>\n            <p>${e.achievements}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderGoldCampaigns(),renderMedals(),renderLegends(),renderReferences(),initThemeToggle()});